const string TokenBucketLua = @"
local key = KEYS[1]
local rate = tonumber(ARGV[1]); local burst = tonumber(ARGV[2]); local cost = tonumber(ARGV[3])
local t = redis.call('TIME'); local now = tonumber(t[1]) + tonumber(t[2]) / 1000000
local b = redis.call('HMGET', key, 'tokens', 'ts')
local tokens = tonumber(b[1]) or burst; local ts = tonumber(b[2]) or now
tokens = math.min(burst, tokens + (now - ts) * rate)
local allowed = tokens >= cost
if allowed then tokens = tokens - cost end
redis.call('HSET', key, 'tokens', tokens, 'ts', now)
redis.call('EXPIRE', key, math.ceil(burst / rate) + 1)
return { allowed and 1 or 0, tostring(tokens) }";

public async Task<bool> TryAcquireAsync(string clientId, double ratePerSec, int burst)
{
    try
    {
        var res = (RedisResult[])(await redis.ScriptEvaluateAsync(TokenBucketLua,
            keys: ["rl:{" + clientId + "}"], values: [ratePerSec, burst, 1]))!;
        return (int)res[0] == 1;
    }
    catch (RedisException)
    {
        metrics.RateLimiterFallback.Add(1);
        return localFallback.TryAcquire(clientId);      // fail open with a conservative local limit
    }
}
