public sealed class K8sConfigProvider(IKubernetes k8s) : IProxyConfigProvider
{
    private volatile InMemoryConfig _config = InMemoryConfig.Empty;
    public IProxyConfig GetConfig() => _config;

    public async Task WatchAsync(CancellationToken ct)
    {
        await foreach (var (_, slice) in k8s.DiscoveryV1.WatchListNamespacedEndpointSliceAsync("payments", labelSelector: "kubernetes.io/service-name=payments-api", cancellationToken: ct))
        {
            var dests = slice.Endpoints.Where(e => e.Conditions?.Ready == true)
                .SelectMany(e => e.Addresses)
                .ToDictionary(a => a, a => new DestinationConfig { Address = $"http://{a}:8080", Health = $"http://{a}:8080/health/ready" });
            var old = _config;
            _config = old.WithCluster("payments", dests, lb: LoadBalancingPolicies.PowerOfTwoChoices);
            old.SignalChange();                                  // YARP reloads atomically
        }
    }
}
