builder.Services.AddReverseProxy().LoadFromConfig(cfg.GetSection("ReverseProxy"))
    .ConfigureHttpClient((ctx, handler) => { handler.ConnectTimeout = TimeSpan.FromSeconds(2); handler.PooledConnectionLifetime = TimeSpan.FromMinutes(2); });

// Custom forwarder step: retry once to a different destination if the connection could not be made
app.MapReverseProxy(p => p.Use(async (ctx, next) =>
{
    await next();
    var err = ctx.GetForwarderErrorFeature();
    if (err?.Error is ForwarderError.RequestCreation or ForwarderError.Request
        && HttpMethods.IsGet(ctx.Request.Method)
        && !ctx.Response.HasStarted
        && retryBudget.TryAcquire(ctx.GetRouteModel().Config.ClusterId!))
    {
        ctx.Features.Set<IForwarderErrorFeature>(null);
        ctx.ReassignProxyRequest(ctx.GetReverseProxyFeature().AvailableDestinations.Skip(1).FirstOrDefault());
        await next();
    }
}));
