// BFF composition with partial results and per-call budgets
app.MapGet("/mobile/home", async (ClaimsPrincipal u, IAccounts acc, IPayments pay, IOffers offers, ICards cards, CancellationToken ct) =>
{
    var id = u.GetCustomerId();
    using var budget = CancellationTokenSource.CreateLinkedTokenSource(ct);
    budget.CancelAfter(TimeSpan.FromMilliseconds(800));                      // screen budget

    var a = Section(() => acc.SummaryAsync(id, budget.Token), critical: true);
    var p = Section(() => pay.RecentAsync(id, 5, budget.Token));
    var o = Section(() => offers.ForCustomerAsync(id, budget.Token));
    var c = Section(() => cards.StatusAsync(id, budget.Token));
    await Task.WhenAll(a, p, o, c);

    if (a.Result.Failed) return Results.Problem("Accounts unavailable", statusCode: 503);
    return Results.Ok(new { accounts = a.Result.Value, recent = p.Result.ValueOrNull, offers = o.Result.ValueOrNull, cards = c.Result.ValueOrNull,
                            degraded = new[] { p, o, c }.Where(t => t.Result.Failed).Select(t => t.Result.Name) });
});

static async Task<SectionResult<T>> Section<T>(Func<Task<T>> call, bool critical = false, [CallerArgumentExpression(nameof(call))] string name = "")
{
    try { return SectionResult<T>.Ok(name, await call()); }
    catch (Exception ex) when (ex is HttpRequestException or OperationCanceledException) { return SectionResult<T>.Fail(name, critical); }
}
