// Service: idempotency key stored atomically with the payment
public async Task<IResult> CreatePayment(CreatePaymentRequest req, [FromHeader(Name = "Idempotency-Key")] Guid key, ClaimsPrincipal u, CancellationToken ct)
{
    var client = u.GetClientId();
    var fingerprint = Convert.ToHexString(SHA256.HashData(JsonSerializer.SerializeToUtf8Bytes(req)));

    var existing = await db.IdempotencyKeys.FindAsync([client, key], ct);
    if (existing is not null)
        return existing.Fingerprint == fingerprint
            ? Results.Json(existing.ResponseBody, statusCode: existing.StatusCode)
            : Results.Problem("Idempotency-Key reused with a different request", statusCode: 422);

    var payment = Payment.Create(req, u.GetCustomerId());
    db.Payments.Add(payment);
    var response = new PaymentCreated(payment.Id, payment.Status.ToString());
    db.IdempotencyKeys.Add(new IdempotencyRecord(client, key, fingerprint, 201, JsonSerializer.SerializeToDocument(response), clock.UtcNow));
    await db.SaveChangesAsync(ct);                   // unique (client, key): concurrent duplicate fails here
    return Results.Created($"/payments/{payment.Id}", response);
}

