// Policy lint run in CI against the merged route set
public static IEnumerable<string> Lint(IReadOnlyList<RouteConfig> routes, IReadOnlyDictionary<string, string> owners)
{
    foreach (var r in routes)
    {
        if (string.IsNullOrEmpty(r.AuthorizationPolicy))
            yield return $"{r.RouteId}: missing AuthorizationPolicy (use 'anonymous' explicitly with justification)";
        if (r.Timeout is null) yield return $"{r.RouteId}: missing Timeout";
        if (string.IsNullOrEmpty(r.RateLimiterPolicy)) yield return $"{r.RouteId}: missing RateLimiterPolicy";
        if (r.Match.Path is "/{**catch-all}" or "/{**rest}") yield return $"{r.RouteId}: catch-all route on shared host";
        var prefix = "/" + r.Match.Path!.Split('/', StringSplitOptions.RemoveEmptyEntries)[0];
        if (!owners.TryGetValue(prefix, out var owner) || owner != r.Metadata?["Team"])
            yield return $"{r.RouteId}: team does not own prefix {prefix}";
    }
    foreach (var dup in routes.GroupBy(x => (x.Match.Path, string.Join(",", x.Match.Methods ?? []))).Where(g => g.Count() > 1))
        yield return $"overlapping routes: {string.Join(", ", dup.Select(d => d.RouteId))}";
}
