// Adaptive concurrency limit per cluster (simplified AIMD)
public sealed class AdaptiveLimiter(int initial, int min, int max)
{
    private int _limit = initial, _inFlight;
    public bool TryEnter() { if (Interlocked.Increment(ref _inFlight) <= Volatile.Read(ref _limit)) return true; Interlocked.Decrement(ref _inFlight); return false; }
    public void Exit(TimeSpan latency, bool failed, TimeSpan target)
    {
        Interlocked.Decrement(ref _inFlight);
        if (failed || latency > target) Volatile.Write(ref _limit, Math.Max(min, (int)(_limit * 0.9)));   // multiplicative decrease
        else if (Random.Shared.Next(10) == 0) Volatile.Write(ref _limit, Math.Min(max, _limit + 1));     // additive increase
    }
}

app.MapReverseProxy(p => p.Use(async (ctx, next) =>
{
    var cfg = ctx.GetRouteModel().Config;
    var limiter = limiters.For(cfg.ClusterId!);
    var priority = cfg.Metadata?.GetValueOrDefault("Priority") ?? "normal";
    if (!limiter.TryEnter() && !(priority == "critical" && reserve.TryEnter()))
    {
        ctx.Response.StatusCode = 503; ctx.Response.Headers.RetryAfter = "2"; return;      // fast rejection
    }
    var sw = Stopwatch.StartNew(); var failed = false;
    try { await next(); failed = ctx.Response.StatusCode >= 500; }
    finally { limiter.Exit(sw.Elapsed, failed, target: TimeSpan.FromMilliseconds(300)); }
}));
