// Rollout gate: synthetic probes for critical routes against the canary cell
public async Task<bool> GateAsync(string cell, CancellationToken ct)
{
    var probes = new[]
    {
        new Probe("login",          HttpMethod.Post, "/auth/token",          expect: 200),
        new Probe("accounts-list",  HttpMethod.Get,  "/v2/accounts",         expect: 200),
        new Probe("payment-quote",  HttpMethod.Post, "/v2/payments/quote",   expect: 200),
        new Probe("unknown-route",  HttpMethod.Get,  "/definitely-not-here", expect: 404)    // deny-by-default still works
    };
    var deadline = clock.UtcNow.AddMinutes(15);
    while (clock.UtcNow < deadline)
    {
        var results = await Task.WhenAll(probes.Select(p => runner.RunAsync(cell, p, ct)));
        if (results.Any(r => !r.Passed)) { await config.RevertAsync(cell, ct); return false; }
        if (await metrics.ErrorRateAsync(cell, TimeSpan.FromMinutes(5), ct) > baseline.ErrorRate * 1.5) { await config.RevertAsync(cell, ct); return false; }
        await Task.Delay(TimeSpan.FromMinutes(1), ct);
    }
    return true;
}
