        return Results.Json(new { error = "invalid_credentials" }, statusCode: 401);   // same response, no enumeration

    var score = await risk.ScoreAsync(ctx.Request.Headers["X-Bot-Score"], ctx.Connection.RemoteIpAddress, req.DeviceId);
    if (score.RequiresChallenge) return Results.Json(new { error = "challenge_required", challenge = score.ChallengeToken }, statusCode: 401);

    var result = await auth.PasswordSignInAsync(req.Username, req.Password);
    if (!result.Succeeded) { await throttle.RecordFailureAsync(req.Username); return Results.Json(new { error = "invalid_credentials" }, statusCode: 401); }
    return result.RequiresMfa ? Results.Json(new { mfa = "required" }, statusCode: 401) : Results.Ok(result.Tokens);
}).RequireRateLimiting("login-ip");
