// Token-budget enforcement and provider fallback (sketch)
app.MapPost("/ai/v1/messages", async (HttpContext ctx, AiRequest req, IBudgets budgets, IModelRouter router, IPiiScanner pii, CancellationToken ct) =>
{
    var caller = ctx.User.GetClientId();
    var estimate = Tokens.Estimate(req.Messages) + req.MaxTokens;
    if (!await budgets.TryReserveAsync(caller, estimate, ct)) return Results.Json(new { error = "token_budget_exceeded" }, statusCode: 429);

    if (pii.Detect(req.Messages) is { HighRisk: true } finding)
        return Results.Json(new { error = "pii_blocked", types = finding.Types }, statusCode: 422);

    foreach (var target in router.Resolve(req.Model, caller))                            // ordered: primary region, secondary, alternate
    {
        var res = await target.SendAsync(req, ct);
        if (res.StatusCode is 429 or >= 500) continue;
        await budgets.SettleAsync(caller, reserved: estimate, actual: res.Usage.InputTokens + res.Usage.OutputTokens, ct);
        meters.Tokens.Add(res.Usage.OutputTokens, new("app", caller), new("model", target.Name));
        return res.ToResult();                                                        // streams through when stream=true
    }
    await budgets.ReleaseAsync(caller, estimate, ct);
    return Results.StatusCode(503);
});
